import java.util.Scanner;
import java.util.Random;

public class GuessMyNumber {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Random random = new Random();

        System.out.println("Welcome to the Guess My Number Game!");
        System.out.println();
        System.out.println("First, let's set the range.");

        // Set the range
        System.out.print("Enter the minimum number (e.g., 1): ");
        int min = scanner.nextInt();

        System.out.print("Enter the maximum number (e.g., 100): ");
        int max = scanner.nextInt();

        // Generate random number within the range
        int secretNumber = random.nextInt(max - min + 1) + min;

        System.out.println();
        System.out.println("I'm thinking of a number between " + min + " and " + max + " (including both). Can you guess what it is?");

        int maxGuesses = 5;
        System.out.println("You have " + maxGuesses + " guesses.");

        int guessesLeft = maxGuesses;
        boolean hasWon = false;

        // Game loop
        while (guessesLeft > 0 && !hasWon) {
            System.out.println();
            System.out.print("Type a number: ");
            int guess = scanner.nextInt();

            // Check if guess is within range
            if (guess < min || guess > max) {
                System.out.println("Your guess (" + guess + ") is out of the range [" + min + ", " + max + "]. Please guess again within the range.");
                continue; // Skip this iteration without decreasing guessesLeft
            }

            // Process valid guess
            System.out.println("Your guess is: " + guess);

            if (guess == secretNumber) {
                System.out.println("The number I was thinking of is: " + secretNumber);
                System.out.println("Congratulations! You guessed it in " + (maxGuesses - guessesLeft + 1) + " attempts!");
                hasWon = true;
            } else if (guess < secretNumber) {
                guessesLeft--;
                System.out.println("Too low! You have " + guessesLeft + " guesses left.");
            } else {
                guessesLeft--;
                System.out.println("Too high! You have " + guessesLeft + " guesses left.");
            }
        }

        // If player didn't win
        if (!hasWon) {
            System.out.println("Sorry, you've run out of guesses. The number was: " + secretNumber);
        }

        scanner.close();
    }
}
```

